// Executes extracted QK ownership with host barriers and the declared scalar
// matrix model. This is not a HIP execution or physical WMMA semantics test.
#include "wave_model.inc"
#include <fstream>
#define __shared__ static
thread_local std::barrier<>* block_barrier=nullptr;
void __syncthreads(){block_barrier->arrive_and_wait();}
void atomicAdd(unsigned* p,unsigned value){*p+=value;}
namespace qrt_blackwell_attention {
#include "scale.inc"
}
namespace qrt_compact_matrix_queue_qk {
namespace group=qrt_sm121_compact_matrix_group;
#include "original_group.inc"
}
namespace qrt_partial_wave_matrix_qk {
namespace partial=qrt_sm121_partial_matrix_group;
namespace group=qrt_sm121_compact_matrix_group;
namespace original=qrt_compact_matrix_queue_qk;
using Row=partial::Row;
struct Original {unsigned tokens;const unsigned *query_domain,*key_domain;unsigned* tile_counts;};
struct Workspace {Original original;const Row *query,*key;};
#include "extracted_scores.inc"
}
namespace partial=qrt_sm121_partial_matrix_group;
namespace original=qrt_q1_moe_hawkeye;
constexpr uint32_t sentinel=0x4f395819u;
uint32_t bits(float x){uint32_t b;std::memcpy(&b,&x,4u);return b;}
float from_bits(uint32_t b){float x;std::memcpy(&x,&b,4u);return x;}
std::vector<uint16_t> read(const char* file,size_t count){
    std::ifstream f(file,std::ios::binary|std::ios::ate);
    if(!f||f.tellg()!=std::streamoff(count*2u))throw std::runtime_error("capture extent");
    std::vector<uint16_t> data(count);f.seekg(0);f.read(reinterpret_cast<char*>(data.data()),std::streamsize(count*2u));
    if(!f)throw std::runtime_error("capture read");return data;
}
struct Counts {uint64_t cases=0,real_cases=0,scores=0,real_scores=0,inactive=0,rejected_tiles=0,shuffles=0,matrices=0;};
template<bool Force>void check(unsigned tokens,unsigned start,unsigned count,unsigned qtile,unsigned ktile,unsigned head,
    unsigned family,unsigned reject,Counts& counts,const std::vector<uint16_t>* real_q=nullptr,const std::vector<uint16_t>* real_k=nullptr){
    const unsigned stride=start+count,qt=qtile*32u,kt=ktile*32u,kv=head/8u;
    std::vector<uint16_t> queries,keys;
    if(real_q){queries=*real_q;keys=*real_k;}
    else{
        queries.resize(size_t(tokens)*4096u);keys.resize(size_t(tokens)*512u);
        for(unsigned side=0u;side<2u;++side){
            auto& data=side?keys:queries;
            for(size_t i=0u;i<data.size();++i){
                const unsigned exponent=family?95u+unsigned((i*19u+i/256u+side*17u)%65u):127u;
                data[i]=uint16_t(((i+side)&1u?0x8000u:0u)|(exponent<<7u)|((i*13u+side*7u)%128u));
                if(i%31u==0u)data[i]=uint16_t(i&1u?0x8000u:0u);
            }
        }
    }
    std::vector<partial::Row> qp(size_t(tokens)*16u*16u),kp(size_t(tokens)*2u*16u);
    std::vector<unsigned> qf(size_t(tokens)*16u,1u),kf(size_t(tokens)*2u,1u);
    for(unsigned row=0u;row<32u&&start+qt+row<tokens;++row){
        const size_t offset=(size_t(start+qt+row)*16u+head)*256u;
        for(unsigned group=0u;group<16u;++group)qp[(size_t(start+qt+row)*16u+head)*16u+group]=partial::prepare(queries.data()+offset+group*16u);
        for(unsigned i=0u;i<256u;++i)qf[(start+qt+row)*16u+head]&=qrt_sm121_narrow_f32_carry::eligible(queries[offset+i]);
    }
    for(unsigned row=0u;row<32u&&kt+row<tokens;++row){
        const size_t offset=(size_t(kt+row)*2u+kv)*256u;
        for(unsigned group=0u;group<16u;++group)kp[(size_t(kv)*16u+group)*tokens+kt+row]=partial::prepare(keys.data()+offset+group*16u);
        for(unsigned i=0u;i<256u;++i)kf[(kt+row)*2u+kv]&=qrt_sm121_narrow_f32_carry::eligible(keys[offset+i]);
    }
    if(reject==1u)qf[(start+qt+31u)*16u+head]=0u;
    if(reject==2u)kf[(kt+31u)*2u+kv]=0u;
    const auto qf_before=qf,kf_before=kf;
    const auto qp_before=qp,kp_before=kp;
    const size_t cells=size_t(count)*16u*stride;
    std::vector<float> output(cells+16u,from_bits(sentinel));
    unsigned statistics[4]={sentinel,0u,0u,sentinel};
    qrt_partial_wave_matrix_qk::Workspace work{{tokens,qf.data(),kf.data(),statistics+1u},qp.data(),kp.data()};
    Wave waves[4];std::barrier<> cta{128};std::vector<std::thread> workers;
    for(unsigned thread=0u;thread<128u;++thread)workers.emplace_back([&,thread]{
        threadIdx.x=thread;blockIdx.x=ktile;blockIdx.y=head;blockIdx.z=qtile;
        wave=&waves[thread/32u];block_barrier=&cta;
        qrt_partial_wave_matrix_qk::scores<Force>(work,output.data()+8u,start,count,stride);
    });
    for(auto& worker:workers)worker.join();
    bool admitted=qt+32u<=count&&kt+32u<=stride&&kt+31u<=start+qt;
    if(admitted)for(unsigned i=0u;i<32u;++i)admitted&=qf[(start+qt+i)*16u+head]&&kf[(kt+i)*2u+kv];
    if(statistics[0]!=sentinel||statistics[3]!=sentinel||statistics[1]!=0u||statistics[2]!=unsigned(admitted))throw std::runtime_error("tile counter differs");
    if(!admitted)++counts.rejected_tiles;
    for(unsigned row=0u;row<count;++row)for(unsigned h=0u;h<16u;++h)for(unsigned key=0u;key<stride;++key){
        const size_t cell=(size_t(row)*16u+h)*stride+key;
        if(!admitted||row<qt||row>=qt+32u||h!=head||key<kt||key>=kt+32u){
            if(bits(output[8u+cell])!=sentinel)throw std::runtime_error("inactive QK cell changed");
            ++counts.inactive;continue;
        }
        original::Value carry{0u,-133,false};
        for(unsigned g=0u;g<16u;++g){
            original::Value terms[17];terms[0]=carry;
            for(unsigned i=0u;i<16u;++i)terms[i+1u]=original::multiply_bf16(
                queries[(size_t(start+row)*16u+head)*256u+g*16u+i],
                keys[(size_t(key)*2u+kv)*256u+g*16u+i],-133);
            carry=original::group_sum<26,-133>(terms,17u);
        }
        if(bits(output[8u+cell])!=bits(original::value_to_float(carry)*qrt_blackwell_attention::kExactScale))throw std::runtime_error("QK score differs");
        ++counts.scores;if(real_q)++counts.real_scores;
    }
    for(unsigned i=0u;i<8u;++i)if(bits(output[i])!=sentinel||bits(output[8u+cells+i])!=sentinel)throw std::runtime_error("QK redzone changed");
    if(qf!=qf_before||kf!=kf_before||std::memcmp(qp.data(),qp_before.data(),qp.size()*sizeof(partial::Row))||
        std::memcmp(kp.data(),kp_before.data(),kp.size()*sizeof(partial::Row)))throw std::runtime_error("QK metadata changed");
    for(const auto& w:waves){counts.shuffles+=w.shuffles;counts.matrices+=w.matrices;}
    ++counts.cases;if(real_q)++counts.real_cases;
}
int main(int argc,char** argv)try{
    if(argc!=3)throw std::runtime_error("original q8192 Q K");
    Counts counts;
    for(unsigned family=0u;family<2u;++family)for(unsigned reject=0u;reject<3u;++reject){
        check<false>(128u,64u,64u,0u,0u,1u,family,reject,counts);
        check<true>(128u,64u,64u,0u,0u,1u,family,reject,counts);
        check<false>(128u,64u,64u,1u,2u,9u,family,reject,counts);
        check<true>(128u,64u,64u,1u,2u,9u,family,reject,counts);
    }
    check<false>(128u,0u,64u,0u,0u,1u,0u,0u,counts);
    check<true>(128u,0u,64u,0u,0u,1u,0u,0u,counts);
    check<false>(128u,64u,33u,1u,0u,9u,0u,0u,counts);
    check<true>(128u,64u,33u,1u,0u,9u,0u,0u,counts);
    const auto q=read(argv[1],8192u*4096u),k=read(argv[2],8192u*512u);
    check<false>(8192u,8064u,128u,3u,254u,15u,0u,0u,counts,&q,&k);
    check<true>(8192u,8064u,128u,3u,254u,15u,0u,0u,counts,&q,&k);
    std::cout<<"{\"cases\":"<<counts.cases<<",\"real_capture_cases\":"<<counts.real_cases<<",\"checked_scores\":"<<counts.scores
      <<",\"real_capture_scores\":"<<counts.real_scores<<",\"inactive_cells\":"<<counts.inactive<<",\"rejected_tiles\":"<<counts.rejected_tiles
      <<",\"uniform_shuffles\":"<<counts.shuffles<<",\"modeled_matrix_instructions\":"<<counts.matrices
      <<",\"raw_bit_mismatches\":0,\"redzones_pass\":true,\"immutable_metadata\":true,\"last_original_query\":8191"
      <<",\"host_coordinates_and_declared_matrix_model_only\":true,\"physical_wmma_semantics_verified\":false,\"gpu_executed\":false}\n";
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 2;}

